package kvm

import "github.com/jetkvm/kvm/internal/native"

// EDIDPreset is an EDID the device offers by name. The list lives here so the
// UI does not carry its own copy and the device decides what it advertises.
type EDIDPreset struct {
	Name string `json:"name"`
	EDID string `json:"edid"`
}

var edidPresets = []EDIDPreset{
	{Name: "JetKVM Default", EDID: native.DefaultEDID},
	{Name: "Samsung SyncMaster, 1792x896", EDID: ""},
	// Samsung SyncMaster EDID with the preferred mode replaced by 1920x800@60 at 2.4:1 to fill
	// the browser video area. The derived presets use internal/edidfit.Mode: CVT standard
	// blanking, widened so the pixel clock keeps the TC358743 CSI output fed (otherwise wide,
	// low-clock modes lose line tails: green stripes). New product code per timing change.
	{Name: "Samsung SyncMaster (wide), 1920x800", EDID: ""},
	// Samsung SyncMaster EDID with the preferred mode replaced by 1440x1088@60 (edidfit.Mode)
	// at 1.32:1 to fill the Galaxy Fold inner screen (2448x1848) in fullscreen.
	{Name: "Samsung SyncMaster (fold), 1440x1088", EDID: ""},
	// Samsung SyncMaster EDID with the preferred mode replaced by 1600x1000@60 (edidfit.Mode)
	// at 16:10; 1680x1050 would exceed the 140 MHz range limit.
	{Name: "Samsung SyncMaster (16:10), 1600x1000", EDID: ""},
}

func rpcGetEDIDPresets() ([]EDIDPreset, error) {
	return edidPresets, nil
}
